/* Struct Layouts */
struct Any {
    const char* _type_name;
    void** _vtable;
};

struct Loadable {
    const char* _type_name;
    void** _vtable;
};

struct Stringable {
    const char* _type_name;
    void** _vtable;
};

struct Class {
    const char* _type_name;
    void** _vtable;
};

struct Introspection {
    const char* _type_name;
    void** _vtable;
};

struct Enum {
    const char* _type_name;
    void** _vtable;
};

struct Buf {
    const char* _type_name;
    void** _vtable;
};

struct Conditional {
    const char* _type_name;
    void** _vtable;
};

struct Dir {
    const char* _type_name;
    void** _vtable;
};

struct Driver {
    const char* _type_name;
    void** _vtable;
};

struct ProgramNode {
    const char* _type_name;
    void** _vtable;
    SpecArray* classes;
};

struct ClassInfo {
    const char* _type_name;
    void** _vtable;
    String name;
    String outerName;
    long long line;
    String sourceFile;
    String baseClass;
    SpecArray* baseClasses;
    SpecArray* typeParams;
    SpecArray* members;
};

struct Member {
    const char* _type_name;
    void** _vtable;
    MemberKind kind;
    long long line;
    String sourceFile;
    SpecArray* modifiers;
    Type* memberType;
    String name;
    SpecArray* params;
    SpecArray* body;
    Expression* initExpr;
    bool hasInit;
    ClassInfo* nestedClass;
};

struct Type {
    const char* _type_name;
    void** _vtable;
    String name;
    SpecArray* params;
};

struct Parameter {
    const char* _type_name;
    void** _vtable;
    String name;
    Type* paramType;
    Expression* defaultExpr;
    bool hasDefault;
};

struct Expression {
    const char* _type_name;
    void** _vtable;
    ExpressionKind kind;
    long long line;
    String resolvedType;
    String str;
    long long num;
    double floatValue;
    SpecArray* pathSegments;
    SpecArray* arrayItems;
    SpecArray* mapKeys;
    SpecArray* mapValues;
    Expression* leftExpr;
    SpecArray* castArgs;
    Expression* methodTarget;
    String methodName;
    SpecArray* methodArgs;
    String bareProvider;
    bool scopedRemainder;
    Expression* rightExpr;
    Expression* unaryExpr;
    Type* anonReturnType;
    SpecArray* anonParams;
    SpecArray* anonBody;
};

struct NamedArg {
    const char* _type_name;
    void** _vtable;
    String name;
    Expression* value;
};

struct Statement {
    const char* _type_name;
    void** _vtable;
    StatementKind kind;
    long long line;
    SpecArray* modifiers;
    Type* varType;
    String varName;
    Expression* initExpr;
    bool hasInit;
    Expression* assignTarget;
    Expression* assignValue;
    Expression* returnExpr;
    bool hasReturnExpr;
    ClassInfo* nestedClass;
    Expression* exprStmt;
    SpecArray* forwardArgs;
};

struct Lexer {
    const char* _type_name;
    void** _vtable;
    String source;
    long long length;
    long long pos;
    long long line;
    long long col;
    SpecArray* errors;
    WellKnown* names;
    Chars* chars;
    ErrorText* errText;
};

